package com.workworth.earnings.api.dto; import com.workworth.earnings.domain.EarningProjection; import java.math.*; import java.time.LocalDate; public record EarningProjectionResponse(LocalDate localDate,String status,long economicSeconds,BigDecimal amount,String currencyCode){public static EarningProjectionResponse from(EarningProjection p){return new EarningProjectionResponse(p.localDate(),p.status().name(),p.economicSeconds(),p.rawAmount()==null?null:p.rawAmount().setScale(2,RoundingMode.HALF_UP),p.currencyCode());}}
